// ***************
// Filename: frame_counter_regs_if.sv
// Author: FPGA Cores 4 U
// Description: Register interface of frame_counter: joins the register map
//   frame_counter_regs (modport regs) and the logic frame_counter (modport
//   core). cfg_* go from the register map to the logic (register values, _wr
//   write pulses, _rd read pulses), sts_* come back (values read, _set / _clr
//   hardware set / clear pulses). A logic block ties every sts_* member it
//   does not use to 0. Generated by ip/scripts/regmap_gen.py from
//   frame_counter_regs.json: edit the JSON and regenerate.
// Date: 2026-10-16
interface frame_counter_regs_if #(
  parameter int NCH = 2
) ();
  logic [NCH-1:0] cfg_irq_en;
  logic cfg_irq_en_wr;
  logic [NCH-1:0] cfg_status;
  logic cfg_status_wr;
  logic [NCH-1:0] sts_status_set;
  logic [NCH-1:0] cfg_clear;
  logic cfg_clear_wr;
  logic [32-1:0] sts_event;
  logic [32-1:0] sts_event_time;
  logic [2-1:0] cfg_event_pop;
  logic cfg_event_pop_wr;
  logic [(NCH)*(32)-1:0] sts_count;
  logic [32-1:0] sts_time;
  logic [NCH-1:0] cfg_ev_en;
  logic cfg_ev_en_wr;

  modport regs (output cfg_irq_en, cfg_irq_en_wr, cfg_status, cfg_status_wr, cfg_clear, cfg_clear_wr,
    cfg_event_pop, cfg_event_pop_wr, cfg_ev_en, cfg_ev_en_wr, input sts_status_set, sts_event, sts_event_time,
    sts_count, sts_time);
  modport core (output sts_status_set, sts_event, sts_event_time, sts_count, sts_time, input cfg_irq_en,
    cfg_irq_en_wr, cfg_status, cfg_status_wr, cfg_clear, cfg_clear_wr, cfg_event_pop, cfg_event_pop_wr,
    cfg_ev_en, cfg_ev_en_wr);
  modport monitor (input cfg_irq_en, cfg_irq_en_wr, cfg_status, cfg_status_wr, cfg_clear, cfg_clear_wr,
    cfg_event_pop, cfg_event_pop_wr, cfg_ev_en, cfg_ev_en_wr, sts_status_set, sts_event, sts_event_time,
    sts_count, sts_time);
endinterface
